/* One Settings page, opened from the menu under your name. Each section either holds the setting
   or links to the area that owns it, so nothing lives in two places. Drawn from the Nov 22 decisions. */
(function(){
  var esc=M.esc, $=M.$, G=DB.GYM, st={edit:false};
  G.address=G.address||"2140 E Douglas Ave, Wichita, KS 67214"; G.color=G.color||"#B23A2B"; G.accent=G.accent||"#E9A23B";
  G.app=G.app||{sched:true,ai:{coach:true,workout:true,plans:false,meals:true}}; G.asst=G.asst||"Milton";
  var AI=[["coach","AI coaching","Members can ask for advice on training and habits."],["workout","AI workout building","Members can have a workout written for them."],["plans","AI nutrition plans","Personal meal plans and ongoing nutrition guidance."],["meals","AI meal logging","Log a meal and get calories and macros back."]];
  var ORDER={pay:"Pay first, then book",book:"Book first, pay at check-in",free:"Book without payment"};
  function sw(act,id,on,label){return '<button class="sw" role="switch" data-act="'+act+'" data-id="'+id+'" aria-checked="'+!!on+'" aria-label="'+esc(label)+'"></button>'}
  function seg(k,cur,opts){return '<div class="seg" role="group">'+opts.map(function(o){return '<button data-act="zrule" data-id="'+k+":"+o[0]+'" aria-pressed="'+(String(cur)===String(o[0]))+'">'+o[1]+'</button>'}).join("")+'</div>'}
  function field(id,label,val,x){return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" value="'+esc(val==null?"":val)+'" autocomplete="off" '+(x||"")+'></div>'}
  function linkRow(t,m,act,id,btn){return '<div class="row"><div class="what"><div class="t">'+t+'</div><div class="m">'+m+'</div></div><div class="acts"><button class="btn sm" data-act="'+act+'" data-id="'+id+'">'+btn+'</button></div></div>'}
  function sec(id,title,sub,body){return '<section class="card" id="z_'+id+'"><div class="ch"><h3>'+title+'</h3>'+(sub?'<span class="m">'+sub+'</span>':"")+'</div>'+body+'</section>'}
  function own(){return DB.SERVICES.filter(function(s){return s.rules&&s.rules.own})}
  function grab(){var r=G.rules, n=function(id,c){var e=$(id); if(!e) return c; var v=parseInt(e.value,10); return isNaN(v)||v<0?c:v}; r.late=n("zLate",r.late); r.notice=n("zNotice",r.notice); r.setup=n("zSetup",r.setup); r.cleanup=n("zClean",r.cleanup)}
  var TABS=[["profile","Your profile"],["gym","Gym"],["team","Team and roles"],["rules","Payments and rules"],["messaging","Calendar and messaging"],["app","Member app"],["milton","Milton"]];
  M.pages.settings={
    title:"Settings",
    tabs:function(){return TABS},
    render:function(r){
      var tab=r.tab||"profile", y=M.you(), R=G.rules, o=own(), h="";
      if(tab==="profile") h=sec("profile","Your profile","Only you see and change this",'<div class="two">'+field("zName","Name",y.name)+field("zPhone","Mobile number",y.phone||"(316) 555-0119")+field("zEmail","Email",y.email)+'<div class="field"><label for="zTz">Time zone</label><select id="zTz"><option>Central Time</option><option>Eastern Time</option><option>Mountain Time</option><option>Pacific Time</option></select></div></div><div class="acts" style="margin-top:14px"><button class="btn hl" data-act="zsave" data-id="profile">Save</button></div>')+sec("role","Your role",null,'<div class="row"><div class="what"><div class="t">'+y.role+" at "+esc(G.name)+'</div><div class="m">An Admin sees and changes everything, including money, roles and these settings.</div></div></div>');
      if(tab==="gym") h=sec("gym","Your gym","What clients see on receipts, links and the app",'<div class="two">'+field("zGym","Gym name",G.name)+field("zAddr","Address",G.address)+field("zSite","Website",G.site)+'<div class="field"><label for="zColor">Brand colors</label><div class="rbar"><input id="zColor" type="color" value="'+G.color+'" aria-label="Main color" style="width:52px;height:40px;padding:3px;flex:none"><input id="zAccent" type="color" value="'+G.accent+'" aria-label="Accent color" style="width:52px;height:40px;padding:3px;flex:none"><span class="m">Main and accent. Used on your booking page, online shop, member app and as "Your gym" in Studio.</span></div></div></div><div class="setrow"><div><b>Logo</b><div class="m">A square image works best. PNG or JPG.</div></div><button class="btn sm" data-act="later" data-id="Uploading a logo">Upload</button></div><div class="acts" style="margin-top:14px"><button class="btn hl" data-act="zsave" data-id="gym">Save</button></div>')+sec("tablets","Rack tablets","Signed in to your gym, so a coach can send a client's workout to one",(G.tablets||[]).map(function(t,i){return '<div class="row"><span class="av" style="border-radius:10px;font-size:10px">iPad</span><div class="what"><input class="fld" data-ztab="'+i+'" value="'+esc(t.name)+'" aria-label="Tablet name" style="max-width:260px"></div><span class="chip ok">Signed in</span><button class="btn sm quiet" data-act="ztabrm" data-id="'+i+'">Remove</button></div>'}).join("")+'<div class="acts" style="margin-top:10px"><button class="btn sm" data-act="panel" data-id="ztab">Add a tablet</button></div><div class="m" style="margin-top:6px">A rack tablet never gets a password. It can only show the workout a coach sends to it. Remove one and it signs out at once.</div>')+sec("hours","Hours","Set once, every service follows unless it has its own",linkRow("Mon to Fri 5:00 AM to 8:00 PM, Sat 8:00 AM to 1:00 PM","Closed Sunday. Date overrides for holidays live with the hours.","go","schedule","Edit hours on Schedule"));
      if(tab==="team") h=sec("team","Team and roles","Who can see and do what",'<div class="strip" style="grid-template-columns:repeat(3,1fr);margin-top:0">'+["Admin","Manager","Coach"].map(function(r){return '<div class="cell"><div class="k">'+r+(r==="Coach"?"es":"s")+'</div><div class="v">'+DB.TEAM.filter(function(t){return t.role===r}).length+'</div></div>'}).join("")+'</div><div class="acts" style="margin-top:14px"><button class="btn hl" data-act="go" data-id="team">Manage team and roles</button></div><div class="m" style="margin-top:8px">Inviting people, changing a role and the switches for what Managers and Coaches can do all live on the Team card.</div>');
      if(tab==="rules") h=sec("pay","Payments","Your payment account, promo codes and what customers get by text",linkRow("Payment account","Payments are live. Cards, cash and checks are on.","zgo","payments:setup","Open Payments setup")+linkRow("Monthly goal",G.goal?M.fm(G.goal)+" a month":"No goal yet","zgo","payments:setup","Change")+'<div class="row"><div class="what"><div class="t">Currency</div><div class="m">One currency for everything you sell.</div></div><select class="csel" id="zCur" aria-label="Currency">'+["USD","CAD","GBP","EUR","AUD"].map(function(c){return '<option'+(R.currency===c?" selected":"")+'>'+c+'</option>'}).join("")+'</select></div>')
        +sec("rules","Booking and cancel rules",o.length?M.plural(DB.SERVICES.length-o.length,"service")+" follow these, "+o.length+" set "+(o.length===1?"its":"their")+" own":"Every service follows these",
          (st.edit?'<div class="two">'+field("zLate","Late cancel window, in hours",R.late,'inputmode="numeric"')+field("zNotice","Booking notice, in hours",R.notice,'inputmode="numeric"')+field("zSetup","Setup time before, in minutes",R.setup,'inputmode="numeric"')+field("zClean","Cleanup time after, in minutes",R.cleanup,'inputmode="numeric"')+'</div><div class="field" style="margin-top:12px"><label>A late cancel</label>'+seg("lateUses",R.lateUses?1:0,[[1,"Uses a session"],[0,"Does not use a session"]])+'</div><div class="field" style="margin-top:12px"><label>A no-show</label>'+seg("noShowUses",R.noShowUses?1:0,[[1,"Uses a session"],[0,"Does not use a session"]])+'</div><div class="field" style="margin-top:12px"><label>Paying and booking</label>'+seg("order",R.order,[["pay",ORDER.pay],["book",ORDER.book],["free",ORDER.free]])+'</div><div class="acts" style="margin-top:14px"><button class="btn hl" data-act="zrulesave">Save defaults</button></div>'
          :'<dl class="vrows">'+[["Late cancel window",R.late?M.plural(R.late,"hour")+" before the session":"No window"],["A late cancel",R.lateUses?"Uses a session":"Does not use a session"],["A no-show",R.noShowUses?"Uses a session":"Does not use a session"],["Booking notice",R.notice?"At least "+M.plural(R.notice,"hour")+" ahead":"None"],["Setup and cleanup",(R.setup?M.plural(R.setup,"minute"):"None")+" before, "+(R.cleanup?M.plural(R.cleanup,"minute"):"none")+" after"],["Paying and booking",ORDER[R.order]]].map(function(x){return '<div><dt>'+x[0]+'</dt><dd>'+x[1]+'</dd></div>'}).join("")+'</dl><div class="acts" style="margin-top:12px"><button class="btn sm" data-act="zruleedit">Edit defaults</button></div>')
          +(o.length?'<div class="infobox" style="margin-top:12px">'+o.map(function(s){return '<button class="link" data-act="zsvc" data-id="'+s.id+'">'+esc(s.name)+'</button>'}).join(", ")+" "+(o.length===1?"sets its":"set their")+' own rules and will not change when you edit these.</div>':""));
      if(tab==="messaging") h=sec("cal","Calendars","Milton books around each coach's connected calendar",linkRow("Connected calendars","4 of 5 team members have connected a calendar.","go","schedule","Open Schedule setup"))+sec("msg","Email, texts and calls","The number and sender your clients see",linkRow("Texting and calling number",G.num+". Calls are recorded with a notice.","zgo","crm:settings","Open messaging settings")+linkRow("Email sender","hello@"+G.site,"zgo","crm:settings","Open messaging settings")+linkRow("Payment link text","What a customer gets when your team texts a link to pay.","zgo","payments:setup","Edit wording"));
      if(tab==="app") h=sec("app","Member app","What your members see when they open the app",'<div class="setrow" style="margin-top:0"><div><b>Scheduling and packages</b><div class="m">Shows the Sessions card on the app\'s Home. Turn it off if your members only train and log food. A booked session always shows.</div></div>'+sw("zapp","sched",G.app.sched,"Scheduling and packages")+'</div>')+sec("ai","AI in the app","The gym default. A membership or subscription can give its members more.",AI.map(function(a){return '<div class="setrow"><div><b>'+a[1]+'</b><div class="m">'+a[2]+'</div></div>'+sw("zai",a[0],G.app.ai[a[0]],a[1])+'</div>'}).join("")+'<div class="m" style="margin-top:10px">When something is off, the member sees a plain message such as "Talk to your gym for access." It never looks like an error. Changes apply right away.</div>');
      if(tab==="milton") h=sec("milton","Milton","Your assistant across the platform and the member app",'<div class="two">'+field("zAsst","Assistant name",G.asst)+'</div><div class="acts" style="margin-top:12px"><button class="btn hl" data-act="zsave" data-id="milton">Save</button></div>'+linkRow("How Milton coaches and talks","Your voice, your methods and what Milton should never say.","go","customize","Open Customize Milton"));
      return '<p class="sub">Everything about your account and your gym in one place. Where an area owns its own settings, the link opens them there.</p><div class="stack">'+h+'</div>';
    },
    brief:function(){var o=own(); return {hd:"Settings for "+G.name+".",items:["<b>Rules.</b> Late cancel inside "+M.plural(G.rules.late,"hour")+". "+(o.length?o.map(function(s){return esc(s.name)}).join(", ")+" "+(o.length===1?"sets its":"set their")+" own.":"Every service follows the defaults."),"<b>AI in the app.</b> "+AI.filter(function(a){return G.app.ai[a[0]]}).map(function(a){return a[1].replace("AI ","")}).join(", ")+" on by default.","<b>Payments.</b> Live. "+(G.goal?"Monthly goal "+M.fm(G.goal)+".":"No monthly goal yet.")],hint:"Ask Milton about settings",sugg:["Where do I change the late cancel window?","Where do I set roles?"]}},
    ask:function(q){
      if(/late cancel/i.test(q)){st.edit=true; M.go({page:"settings",tab:"rules"}); M.say(q,"Here, under Booking and cancel rules. I opened it for editing. Services that set their own rules keep them."); return true}
      if(/role/i.test(q)){M.go({page:"settings",tab:"team"}); M.say(q,"Roles are set on the Team card. This section lists who has which role and links there."); return true}
      return false;
    }
  };
  var A=M.acts;
  A.zgo=function(id){var a=id.split(":"); M.go({page:a[0],tab:a[1]})};
  A.zsvc=function(id){M.go({page:"services",tab:"services",id:id})};
  A.zsave=function(id){
    if(id==="profile"){var y=M.you(), n=$("zName").value.trim(); if(!n) return M.toast("Add your name."); y.name=n; y.phone=$("zPhone").value.trim(); y.email=$("zEmail").value.trim()}
    if(id==="gym"){var g=$("zGym").value.trim(); if(!g) return M.toast("Add the gym's name."); G.name=g; G.address=$("zAddr").value.trim(); G.site=$("zSite").value.trim(); G.color=$("zColor").value; G.accent=$("zAccent").value}
    if(id==="milton"){G.asst=$("zAsst").value.trim()||"Milton"}
    M.render(); M.toast("Saved.");
  };
  var zt={err:"",code:"",name:""};
  M.panels.ztab=function(){
    return '<div class="sph"><div><h3>Add a tablet</h3><div class="m">For a tablet that sits at a rack or platform.</div></div>'+M.px+'</div><div class="spb"><div class="infobox"><span>On the tablet, open Milton and tap <b>Set up as a rack tablet</b> on the login page. It shows a code.</span></div><div class="field"><label for="ztCode">Code on the tablet</label><input class="fld" id="ztCode" placeholder="Like K7M 4QP" autocomplete="off" value="'+esc(zt.code)+'" style="text-transform:uppercase;letter-spacing:.06em"></div><div class="field"><label for="ztName">Name it for where it sits</label><input class="fld" id="ztName" value="'+esc(zt.name||"Rack "+(G.tablets.length+1)+" iPad")+'"></div>'+(zt.err?'<div class="m" role="alert" style="color:var(--err);font-weight:600">'+zt.err+'</div>':"")+'</div><div class="spf"><button class="btn pri" data-act="ztabadd">Add tablet</button><button class="btn" data-act="pclose">Cancel</button></div>';
  };
  A.ztabadd=function(){var c=(document.getElementById("ztCode").value||"").replace(/\s/g,"").toUpperCase(), n=document.getElementById("ztName").value.trim(); zt.code=c; zt.name=n;
    if(!/^[A-Z0-9]{6}$/.test(c)){zt.err=c?"That code does not match a tablet waiting to be set up. Check the tablet and try again.":"Type the code showing on the tablet."; return M.renderPanel()}
    if(!n){zt.err="Give the tablet a name."; return M.renderPanel()}
    G.tablets.push({id:"t"+Date.now(),name:n}); zt={err:"",code:"",name:""}; M.closePanel(); M.render(); M.toast(n+" is signed in and ready. Prototype only, nothing was paired.")};
  A.ztabrm=function(id){var t=G.tablets.splice(+id,1)[0]; M.render(); M.toast(t.name+" removed.",function(){G.tablets.splice(+id,0,t); M.render()})};
  A.zruleedit=function(){st.edit=true; M.render()};
  A.zrule=function(id){grab(); var a=id.split(":"); if(a[0]==="order") G.rules.order=a[1]; else G.rules[a[0]]=a[1]==="1"; M.render()};
  A.zrulesave=function(){grab(); st.edit=false; var n=DB.SERVICES.length-own().length; M.render(); M.toast("Defaults saved. "+M.plural(n,"service")+" follow them.")};
  A.zapp=function(id){G.app[id]=!G.app[id]; M.render(); M.toast(G.app[id]?"The Sessions card shows in the member app.":"The Sessions card is hidden in the member app.")};
  A.zai=function(id){G.app.ai[id]=!G.app.ai[id]; M.render(); M.toast("Saved. The change applies right away.")};
  M.changes.push(function(el){ if(el.dataset&&el.dataset.ztab){var v=el.value.trim(); if(v) G.tablets[+el.dataset.ztab].name=v; return M.toast("Renamed.")} if(el.id==="zCur"){G.rules.currency=el.value; M.toast("Currency set to "+el.value+".")} });
})();
